<?php declare(strict_types=1); ?>
<?php if(!$runs): ?><p class="empty">Noch keine Spawnläufe. Nach dem Speichern führt der nächste fällige Worker-Lauf die Regeln aus.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Zeit (UTC)</th><th>Status</th><th>Rohstoffe</th><th>Monster</th><th>Freie Dörfer</th><th>Entfernt</th><th>Details</th></tr></thead><tbody><?php foreach($runs as $run): $details=json_decode($run['details_json']??'{}',true)?:[]; ?><tr><td><?= ah($run['created_at']) ?></td><td><span class="pill"><?= ah($run['status']) ?></span></td><td>+<?= an($run['resources_spawned']) ?></td><td>+<?= an($run['monsters_spawned']) ?></td><td>+<?= an($details['villages_spawned']??0) ?></td><td><?= an($run['expired_removed']) ?></td><td><details><summary>Anzeigen</summary><pre><?= ah(json_encode($details,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre></details></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
